<?php require '../../config/database.php';require '../../includes/functions.php';require_admin();$id=(int)($_GET['id']??0);$r=['name'=>'','room_type'=>'Deluxe','bed_type'=>'Queen Bed','capacity'=>2,'price_per_night'=>'','short_description'=>'','description'=>'','amenities'=>'WiFi, Air Conditioning, TV, Private Bathroom','image_url'=>'https://images.unsplash.com/photo-1611892440504-42a792e24d32?auto=format&fit=crop&w=1200&q=80','status'=>'available'];if($id){$st=$pdo->prepare("SELECT * FROM rooms WHERE id=?");$st->execute([$id]);$r=$st->fetch()?:$r;}$formError = '';
if($_SERVER['REQUEST_METHOD']==='POST'){
verify_csrf();
$name=trim((string)($_POST['name']??'')); $type=trim((string)($_POST['room_type']??'')); $bed=trim((string)($_POST['bed_type']??''));
$capacity=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>50]]);
$price=filter_var($_POST['price_per_night']??null,FILTER_VALIDATE_FLOAT);
$imageUrl=trim((string)($_POST['image_url']??'')); $status=(string)($_POST['status']??'');
if($name===''||$type===''||$bed===''||$capacity===false||$price===false||$price<0||!in_array($status,['available','maintenance'],true)||($imageUrl!==''&&(!filter_var($imageUrl,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($imageUrl,PHP_URL_SCHEME)),['http','https'],true)))){
    $formError='Enter valid room details. Capacity must be 1–50, price must be non-negative, status must be valid, and image URL must be a valid URL.';
} else {
$v=[$name,$type,$bed,(int)$capacity,(float)$price,trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),trim((string)($_POST['amenities']??'')),$imageUrl,$status];if($id){$v[]=$id;$pdo->prepare("UPDATE rooms SET name=?,room_type=?,bed_type=?,capacity=?,price_per_night=?,short_description=?,description=?,amenities=?,image_url=?,status=? WHERE id=?")->execute($v);}else{$pdo->prepare("INSERT INTO rooms(name,room_type,bed_type,capacity,price_per_night,short_description,description,amenities,image_url,status) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute($v);}flash('success','Room saved.');header('Location: '.url('admin/rooms/index.php'));exit;
}
}
$page_title=$id?'Edit Room':'Add Room';include '../../includes/header.php';?><div class="container page-hero"><h1><?=$id?'Edit':'Add'?> room</h1></div><section style="padding-top:5px"><div class="container"><?php if($formError): ?><div class="flash error"><?=e($formError)?></div><?php endif; ?><form method="post" class="card admin-form" data-confirm="Save these room details and availability settings?" data-confirm-title="Save room changes"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="grid" style="grid-template-columns:1fr 1fr"><div class="form-group"><label>Name</label><input class="input" name="name" value="<?=e($r['name'])?>" required></div><div class="form-group"><label>Room type</label><input class="input" name="room_type" value="<?=e($r['room_type'])?>" required></div><div class="form-group"><label>Bed type</label><input class="input" name="bed_type" value="<?=e($r['bed_type'])?>" required></div><div class="form-group"><label>Capacity</label><input class="input" type="number" name="capacity" min="1" value="<?=e($r['capacity'])?>" required></div><div class="form-group"><label>Price / night</label><input class="input" type="number" step=".01" name="price_per_night" value="<?=e($r['price_per_night'])?>" required></div><div class="form-group"><label>Status</label><select class="select" name="status"><option value="available" <?=$r['status']==='available'?'selected':''?>>Available</option><option value="maintenance" <?=$r['status']==='maintenance'?'selected':''?>>Maintenance</option></select></div></div><div class="form-group"><label>Short description</label><input class="input" name="short_description" value="<?=e($r['short_description'])?>"></div><div class="form-group"><label>Full description</label><textarea name="description" rows="4"><?=e($r['description'])?></textarea></div><div class="form-group"><label>Amenities (comma separated)</label><input class="input" name="amenities" value="<?=e($r['amenities'])?>"></div><div class="form-group"><label>Image URL</label><input class="input" name="image_url" value="<?=e($r['image_url'])?>"></div><button class="btn btn-primary">Save room</button></form></div></section><?php include '../../includes/footer.php';?>